import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { getJson } from '../api/client'
import type { MeResponse, Tenant } from '../api/types'

type ActorState = { actorEmail: string; tenant: Tenant | null; generation: number; loading: boolean; error: string | null; writeInFlight: boolean; beginWrite: (key: string) => boolean; endWrite: (key: string) => void; switchActor: (email: string) => void; retry: () => void }
const ActorContext = createContext<ActorState | null>(null)

export function ActorProvider({ children }: { children: ReactNode }) {
  const [actorEmail, setActorEmail] = useState('alice@east.test')
  const [tenant, setTenant] = useState<Tenant | null>(null)
  const [generation, setGeneration] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [writeInFlight, setWriteInFlight] = useState(false)
  const activeWriteKeys = useRef(new Set<string>())
  const requestId = useRef(0)

  useEffect(() => {
    const id = ++requestId.current
    const controller = new AbortController()
    setLoading(true); setError(null); setTenant(null)
    getJson<MeResponse>('/api/me', actorEmail, controller.signal).then(data => {
      if (id === requestId.current) { setTenant(data.tenant); setLoading(false) }
    }).catch(cause => {
      if (id !== requestId.current || controller.signal.aborted) return
      setError(cause instanceof Error ? cause.message : '无法确认管理员身份'); setLoading(false)
    })
    return () => { controller.abort(); requestId.current++ }
  }, [actorEmail, generation])

  const switchActor = useCallback((email: string) => {
    if (!writeInFlight && email !== actorEmail) { setTenant(null); setLoading(true); setActorEmail(email); setGeneration(value => value + 1) }
  }, [actorEmail, writeInFlight])
  const retry = useCallback(() => setGeneration(value => value + 1), [])
  const beginWrite = useCallback((key: string) => {
    if (activeWriteKeys.current.has(key)) return false
    activeWriteKeys.current.add(key)
    setWriteInFlight(true)
    return true
  }, [])
  const endWrite = useCallback((key: string) => {
    activeWriteKeys.current.delete(key)
    setWriteInFlight(activeWriteKeys.current.size > 0)
  }, [])
  return <ActorContext.Provider value={{ actorEmail, tenant, generation, loading, error, writeInFlight, beginWrite, endWrite, switchActor, retry }}>{children}</ActorContext.Provider>
}

export function useActor(): ActorState {
  const context = useContext(ActorContext)
  if (!context) throw new Error('ActorProvider is missing')
  return context
}
export type PendingWrite = { actorEmail: string; method: 'POST'; path: string; body: object; key: string; createdAt: number }
const storageKey = 'ocean-pending-write'
export function createPendingWrite(actorEmail: string, path: string, body: object): PendingWrite { return { actorEmail, method: 'POST', path, body, key: crypto.randomUUID(), createdAt: Date.now() } }
function readPending(): PendingWrite[] {
  const raw = sessionStorage.getItem(storageKey)
  if (!raw) return []
  try {
    const values = JSON.parse(raw) as unknown
    return Array.isArray(values) ? values.filter((value): value is PendingWrite => value?.method === 'POST' && typeof value.key === 'string' && typeof value.path === 'string') : []
  } catch { return [] }
}
export function loadPendingWrite(actorEmail?: string, path?: string): PendingWrite | null {
  return readPending().filter(value => (!actorEmail || value.actorEmail === actorEmail) && (!path || value.path === path)).at(-1) ?? null
}
export function savePendingWrite(write: PendingWrite): void {
  const values = readPending().filter(value => value.key !== write.key)
  values.push(write)
  sessionStorage.setItem(storageKey, JSON.stringify(values))
}
export function clearPendingWrite(write?: PendingWrite): void {
  if (!write) { sessionStorage.removeItem(storageKey); return }
  sessionStorage.setItem(storageKey, JSON.stringify(readPending().filter(value => value.key !== write.key)))
}
import type { PendingWrite } from './pendingWrite'
import { clearPendingWrite, savePendingWrite } from './pendingWrite'
import { postJson } from '../api/client'

export async function submitWrite<T>(write: PendingWrite): Promise<T> {
  savePendingWrite(write)
  const result = await postJson<T>(write.path, write.actorEmail, write.key, write.body)
  clearPendingWrite(write)
  return result
}

import { useEffect, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import { getJson } from '../api/client'
import type { CertificateListResponse } from '../api/types'
import { useActor } from '../actor/ActorProvider'
import { CertificateDrawer } from './CertificateDrawer'
import { exportCertificates } from '../features/certificates/exportCsv'

const sortOptions = ['issued_local_date', 'learner_name', 'course_title', 'serial_number'] as const
type Sort = typeof sortOptions[number]

export function CertificatesPage() {
  const { actorEmail, tenant } = useActor()
  const [params, setParams] = useSearchParams()
  const [data, setData] = useState<CertificateListResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<number | null>(null)
  const [revision, setRevision] = useState(0)
  const [exportBusy, setExportBusy] = useState(false)
  const [exportError, setExportError] = useState<string | null>(null)
  const search = params.get('search') ?? ''
  const candidate = params.get('sort')
  const sort: Sort = sortOptions.includes(candidate as Sort) ? candidate as Sort : 'issued_local_date'
  const direction = params.get('direction') === 'asc' ? 'asc' : 'desc'
  const page = Math.max(1, Number(params.get('page')) || 1)

  useEffect(() => {
    if (!tenant) { setData(null); return }
    const controller = new AbortController()
    setLoading(true); setError(null)
    const query = new URLSearchParams({ search, sort, direction, page: String(page), page_size: '20' })
    getJson<CertificateListResponse>(`/api/certificates?${query}`, actorEmail, controller.signal).then(result => {
      if (!controller.signal.aborted) { setData(result); setLoading(false) }
    }).catch(cause => {
      if (!controller.signal.aborted) { setError(cause instanceof Error ? cause.message : '加载证书失败'); setLoading(false) }
    })
    return () => controller.abort()
  }, [actorEmail, tenant?.id, search, sort, direction, page, revision])

  function updateParam(name: string, value: string, resetPage = false) {
    const next = new URLSearchParams(params)
    next.set(name, value)
    if (resetPage) next.set('page', '1')
    setParams(next)
  }
  async function exportCurrent() {
    if (!tenant || exportBusy) return
    const capturedActor = actorEmail
    const capturedTenant = tenant.name
    setExportBusy(true); setExportError(null)
    try { await exportCertificates(capturedActor, { search, sort, direction }, capturedTenant) }
    catch (cause) { setExportError(cause instanceof Error ? cause.message : '导出失败') }
    finally { setExportBusy(false) }
  }
  return <section>
    <div className="page-heading"><div><h1>证书</h1><p>{tenant?.name} · {tenant?.timezone}</p></div><button type="button" disabled={!tenant || exportBusy} onClick={exportCurrent}>{exportBusy ? `正在导出 ${tenant?.name}…` : '导出 CSV'}</button></div>
    {exportError && <p role="alert">{exportError} <button type="button" onClick={exportCurrent}>重试导出</button></p>}
    <div className="filters"><label>搜索学员或序列号<input type="search" value={search} onChange={event => updateParam('search', event.target.value, true)} /></label>
      <label>排序字段<select value={sort} onChange={event => updateParam('sort', event.target.value, true)}>{sortOptions.map(value => <option key={value} value={value}>{({ issued_local_date: '签发日期', learner_name: '学员', course_title: '课程', serial_number: '序列号' })[value]}</option>)}</select></label>
      <button type="button" onClick={() => updateParam('direction', direction === 'asc' ? 'desc' : 'asc', true)} aria-label="切换排序方向">{direction === 'asc' ? '升序 ↑' : '降序 ↓'}</button></div>
    {loading && <p role="status">正在加载证书…</p>}
    {!loading && error && <div role="alert">{error} <button type="button" onClick={() => setRevision(value => value + 1)}>重试列表</button></div>}
    {!loading && !error && data && (data.items.length === 0 ? <p className="empty-state">{search ? '没有匹配的证书' : '暂无证书'}</p> : <>
      <div className="table-scroll"><table><thead><tr><th>序列号</th><th>学员</th><th>课程</th><th>签发日期</th><th>状态</th></tr></thead><tbody>{data.items.map(item => <tr key={item.id}>
        <td><button type="button" className="text-button" onClick={() => setSelectedId(item.id)}>{item.serial_number}</button></td><td>{item.learner_name}</td><td>{item.course_title}</td><td>{item.issued_local_date}</td><td><span className={`status ${item.status.toLowerCase()}`}>{item.status === 'ACTIVE' ? '有效' : '已撤销'}</span></td>
      </tr>)}</tbody></table></div>
      <div className="pagination"><span>共 {data.total} 条 · 第 {page} 页</span><button type="button" disabled={page <= 1} onClick={() => updateParam('page', String(page - 1))}>上一页</button><button type="button" disabled={page * 20 >= data.total} onClick={() => updateParam('page', String(page + 1))}>下一页</button></div>
    </>)}
    {selectedId !== null && <CertificateDrawer id={selectedId} actorEmail={actorEmail} onClose={() => setSelectedId(null)} onChanged={() => setRevision(value => value + 1)} />}
  </section>
}
import type { BulkIssueResponse } from '../api/types'

export function BulkIssueResults({ result }: { result: BulkIssueResponse }) {
  return <section className="result-panel" aria-label="批量颁发结果"><h2>操作已完成</h2><p>已颁发 {result.summary.issued} · 已跳过 {result.summary.skipped} · 失败 {result.summary.failed}</p>
    <div className="table-scroll"><table><thead><tr><th>学员</th><th>结果</th><th>原因 / 序列号</th></tr></thead><tbody>{result.outcomes.map(outcome => <tr key={outcome.learner_id}><td>{outcome.learner_name}</td><td>{outcome.result === 'issued' ? '已颁发' : outcome.result === 'skipped' ? '已跳过' : '失败'}</td><td>{outcome.serial_number ?? outcome.reason ?? '—'}</td></tr>)}</tbody></table></div>
  </section>
}
import { useEffect, useRef, useState } from 'react'
import type { RevokeResponse } from '../api/types'
import { createPendingWrite, loadPendingWrite, type PendingWrite } from '../lib/pendingWrite'
import { submitWrite } from '../lib/writeRequest'

type Props = { id: number; serial: string; actorEmail: string; onDone: () => void; onClose: () => void; onBeginWrite?: (key: string) => boolean; onEndWrite?: (key: string) => void }

export function RevokeDialog({ id, serial, actorEmail, onDone, onClose, onBeginWrite, onEndWrite }: Props) {
  const path = `/api/certificates/${id}/revoke`
  const [write, setWrite] = useState<PendingWrite | null>(() => {
    return loadPendingWrite(actorEmail, path)
  })
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [result, setResult] = useState<RevokeResponse | null>(null)
  const confirmRef = useRef<HTMLButtonElement>(null)
  useEffect(() => { confirmRef.current?.focus() }, [])
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape' && !busy) onClose() }
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [busy, onClose])

  async function confirm() {
    const operation = write ?? createPendingWrite(actorEmail, path, {})
    if (onBeginWrite && !onBeginWrite(operation.key)) { setError('该操作正在处理中'); return }
    setWrite(operation); setBusy(true); setError(null)
    try {
      const response = await submitWrite<RevokeResponse>(operation)
      setResult(response)
      onDone()
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : '请求结果不确定，请用原操作重试')
    } finally { setBusy(false); onEndWrite?.(operation.key) }
  }

  return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-label="撤销证书确认">
    <h2>撤销证书</h2><p>请确认撤销以下证书：</p><strong>{serial}</strong>
    {result ? <p role="status">{result.changed ? '撤销成功' : '证书已撤销，无需重复操作'}</p> : <p>撤销后可再次颁发新证书，旧证书仍保留。</p>}
    {error && <p role="alert">{error}</p>}
    <div className="modal-actions"><button type="button" onClick={onClose} disabled={busy}>{result ? '关闭' : '取消'}</button>{!result && <button ref={confirmRef} type="button" onClick={confirm} disabled={busy}>{busy ? '处理中…' : error ? '用同一操作重试' : '确认撤销'}</button>}</div>
  </div></div>
}

export type Tenant = { id: number; name: string; timezone: string }
export type MeResponse = { admin: { id: number; email: string }; tenant: Tenant }
export type Course = { id: number; title: string }
export type CoursesResponse = { items: Course[] }
export type Enrollment = { learner_id: number; learner_name: string; status: 'COMPLETED' | 'INCOMPLETE'; active_certificate_id: number | null }
export type EnrollmentsResponse = { course: Course; items: Enrollment[] }
export type CertificateStatus = 'ACTIVE' | 'REVOKED'
export type CertificateSummary = { id: number; serial_number: string; learner_name: string; course_title: string; issued_local_date: string; status: CertificateStatus }
export type CertificateListResponse = { items: CertificateSummary[]; page: number; page_size: number; total: number }
export type CertificateDetail = CertificateSummary & { issued_local_datetime: string }
export type BulkOutcome = { learner_id: number; learner_name: string; result: 'issued' | 'skipped' | 'failed'; reason: string | null; certificate_id: number | null; serial_number: string | null }
export type BulkIssueResponse = { operation_id: number; status: 'COMPLETED'; summary: { issued: number; skipped: number; failed: number }; outcomes: BulkOutcome[] }
export type RevokeResponse = { operation_id: number; certificate_id: number; status: 'REVOKED'; changed: boolean }
export class ApiError extends Error {
  constructor(public status: number, message: string) { super(message); this.name = 'ApiError' }
}

async function parseJson<T>(response: Response): Promise<T> {
  let body: unknown
  try { body = await response.json() } catch { body = null }
  if (!response.ok) {
    const message = typeof body === 'object' && body !== null && 'message' in body && typeof body.message === 'string' ? body.message : `请求失败（${response.status}）`
    throw new ApiError(response.status, message)
  }
  return body as T
}

export async function getJson<T>(path: string, actorEmail: string, signal?: AbortSignal): Promise<T> {
  const response = await fetch(path, { headers: { 'X-Actor-Email': actorEmail }, cache: 'no-store', signal })
  return parseJson<T>(response)
}

export async function postJson<T>(path: string, actorEmail: string, key: string, body: object = {}): Promise<T> {
  const response = await fetch(path, { method: 'POST', headers: { 'X-Actor-Email': actorEmail, 'Idempotency-Key': key, 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  return parseJson<T>(response)
}
export async function exportCertificates(actorEmail: string, filters: { search: string; sort: string; direction: 'asc' | 'desc' }, tenantName: string): Promise<void> {
  const query = new URLSearchParams({ search: filters.search, sort: filters.sort, direction: filters.direction })
  const response = await fetch(`/api/certificates/export?${query}`, { headers: { 'X-Actor-Email': actorEmail }, cache: 'no-store' })
  if (!response.ok) throw new Error(`导出失败（${response.status}）`)
  const objectUrl = URL.createObjectURL(await response.blob())
  const link = document.createElement('a')
  link.href = objectUrl
  link.download = `certificates-${tenantName.replace(/[^\p{L}\p{N}_-]/gu, '_')}.csv`
  document.body.append(link)
  try { link.click() } finally { link.remove(); URL.revokeObjectURL(objectUrl) }
}

