import sqlite3


SORT_COLUMNS = {
    "issued_local_date": "certificates.issued_local_date",
    "learner_name": "learners.name COLLATE NOCASE",
    "course_title": "courses.title COLLATE NOCASE",
    "serial_number": "certificates.serial_number COLLATE NOCASE",
}
FROM_CERTIFICATES = (
    "FROM certificates "
    "JOIN learners ON learners.id = certificates.learner_id AND learners.tenant_id = certificates.tenant_id "
    "JOIN courses ON courses.id = certificates.course_id AND courses.tenant_id = certificates.tenant_id "
)
SUMMARY_COLUMNS = (
    "certificates.id, certificates.serial_number, learners.name AS learner_name, "
    "courses.title AS course_title, certificates.issued_local_date, certificates.status"
)


def certificate_where(tenant_id: int, search: str) -> tuple[str, tuple]:
    if not search:
        return "WHERE certificates.tenant_id = ?", (tenant_id,)
    escaped = search.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    term = f"%{escaped}%"
    return (
        "WHERE certificates.tenant_id = ? AND "
        "(learners.name LIKE ? ESCAPE '\\' COLLATE NOCASE OR "
        "certificates.serial_number LIKE ? ESCAPE '\\' COLLATE NOCASE)",
        (tenant_id, term, term),
    )


def certificate_order(sort: str, direction: str) -> str:
    return f"ORDER BY {SORT_COLUMNS[sort]} {direction.upper()}, certificates.id ASC"


def list_certificates(
    conn: sqlite3.Connection,
    tenant_id: int,
    search: str,
    sort: str,
    direction: str,
    page: int,
    page_size: int,
) -> dict:
    where, params = certificate_where(tenant_id, search)
    conn.execute("BEGIN")
    try:
        total = conn.execute(f"SELECT COUNT(*) {FROM_CERTIFICATES} {where}", params).fetchone()[0]
        rows = conn.execute(
            f"SELECT {SUMMARY_COLUMNS} {FROM_CERTIFICATES} {where} "
            f"{certificate_order(sort, direction)} LIMIT ? OFFSET ?",
            (*params, page_size, (page - 1) * page_size),
        ).fetchall()
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    return {"items": [dict(row) for row in rows], "page": page, "page_size": page_size, "total": total}


def get_certificate(conn: sqlite3.Connection, tenant_id: int, certificate_id: int) -> dict | None:
    row = conn.execute(
        f"SELECT {SUMMARY_COLUMNS}, certificates.issued_at_utc {FROM_CERTIFICATES} "
        "WHERE certificates.tenant_id = ? AND certificates.id = ?",
        (tenant_id, certificate_id),
    ).fetchone()
    return dict(row) if row else None

from pathlib import Path

from .actor import ActorContext
from .audit_repo import record_event
from .db import connect
from .dates import utc_now_text
from .errors import ApiError
from .idempotency import execute_write, fingerprint


def revoke_certificate(path: Path, actor: ActorContext, certificate_id: int, key: str, body: dict) -> tuple[int, dict]:
    conn = connect(path)
    try:
        request_fingerprint = fingerprint("POST", "/api/certificates/{certificate_id}/revoke", certificate_id, body)

        def validate_new_request() -> None:
            if body:
                raise ApiError(422, "INVALID_REQUEST", "请求体不支持额外字段")
            found = conn.execute(
                "SELECT 1 FROM certificates WHERE tenant_id = ? AND id = ?",
                (actor.tenant_id, certificate_id),
            ).fetchone()
            if found is None:
                raise ApiError(404, "NOT_FOUND", "资源不存在")

        def perform(record_id: int) -> tuple[int, dict]:
            now = utc_now_text()
            changed = conn.execute(
                "UPDATE certificates SET status = 'REVOKED', revoked_at_utc = ? "
                "WHERE tenant_id = ? AND id = ? AND status = 'ACTIVE'",
                (now, actor.tenant_id, certificate_id),
            ).rowcount == 1
            if changed:
                record_event(conn, actor.tenant_id, certificate_id, actor.admin_id, "REVOKED", now, record_id)
            return 200, {
                "operation_id": record_id,
                "certificate_id": certificate_id,
                "status": "REVOKED",
                "changed": changed,
            }

        return execute_write(conn, actor, key, request_fingerprint, "REVOKE", validate_new_request, perform)
    finally:
        conn.close()

from collections.abc import Callable
from hashlib import sha256
import json
import sqlite3

from .actor import ActorContext
from .dates import utc_now_text
from .errors import ApiError


def validate_key(key: str | None) -> str:
    if key is None or not 1 <= len(key) <= 128 or any(not 33 <= ord(char) <= 126 for char in key):
        raise ApiError(422, "INVALID_IDEMPOTENCY_KEY", "幂等键无效")
    return key


def parse_write_body(raw: bytes) -> dict:
    if not raw:
        return {}
    try:
        value = json.loads(raw)
    except (ValueError, UnicodeDecodeError):
        raise ApiError(422, "INVALID_REQUEST", "请求体必须是 JSON 对象") from None
    if not isinstance(value, dict):
        raise ApiError(422, "INVALID_REQUEST", "请求体必须是 JSON 对象")
    return value


def fingerprint(method: str, route_template: str, target_id: int, body: dict) -> str:
    canonical = json.dumps(
        {"method": method, "route": route_template, "target_id": target_id, "body": body},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    return sha256(canonical.encode("utf-8")).hexdigest()


def execute_write(
    conn: sqlite3.Connection,
    actor: ActorContext,
    key: str,
    request_fingerprint: str,
    operation_type: str,
    validate_new_request: Callable[[], None],
    perform: Callable[[int], tuple[int, dict]],
) -> tuple[int, dict]:
    try:
        conn.execute("BEGIN IMMEDIATE")
        record = conn.execute(
            "SELECT request_fingerprint, response_status, response_body_json FROM idempotency_records "
            "WHERE tenant_id = ? AND actor_id = ? AND idempotency_key = ?",
            (actor.tenant_id, actor.admin_id, key),
        ).fetchone()
        if record is not None:
            if record["request_fingerprint"] != request_fingerprint:
                raise ApiError(409, "IDEMPOTENCY_CONFLICT", "此操作键已用于另一请求")
            if record["response_status"] is None or record["response_body_json"] is None:
                raise ApiError(503, "OPERATION_PENDING", "操作尚未完成，请用原键重试")
            result = record["response_status"], json.loads(record["response_body_json"])
            conn.commit()
            return result

        validate_new_request()
        record_id = conn.execute(
            "INSERT INTO idempotency_records "
            "(tenant_id, actor_id, idempotency_key, request_fingerprint, operation_type, created_at_utc) "
            "VALUES (?, ?, ?, ?, ?, ?)",
            (actor.tenant_id, actor.admin_id, key, request_fingerprint, operation_type, utc_now_text()),
        ).lastrowid
        status, body = perform(record_id)
        conn.execute(
            "UPDATE idempotency_records SET response_status = ?, response_body_json = ?, completed_at_utc = ? WHERE id = ?",
            (status, json.dumps(body, ensure_ascii=False, separators=(",", ":")), utc_now_text(), record_id),
        )
        conn.commit()
        return status, body
    except sqlite3.OperationalError as error:
        conn.rollback()
        if "locked" in str(error).lower() or "busy" in str(error).lower():
            raise ApiError(503, "DATABASE_BUSY", "服务暂时繁忙，请用原操作重试") from error
        raise
    except Exception:
        conn.rollback()
        raise

