    <div className="page-heading"><div><h1>证书</h1><p>{tenant?.name} · {tenant?.timezone}</p></div><button type="button" disabled={!tenant || exportBusy} onClick={exportCurrent}>{exportBusy ? `正在导出 ${tenant?.name}…` : '导出 CSV'}</button></div>
    {exportError && <p role="alert">{exportError} <button type="button" onClick={exportCurrent}>重试导出</button></p>}
    <div className="filters"><label>搜索学员或序列号<input type="search" value={search} onChange={event => updateParam('search', event.target.value, true)} /></label>
      <label>排序字段<select value={sort} onChange={event => updateParam('sort', event.target.value, true)}>{sortOptions.map(value => <option key={value} value={value}>{({ issued_local_date: '签发日期', learner_name: '学员', course_title: '课程', serial_number: '序列号' })[value]}</option>)}</select></label>
      <button type="button" onClick={() => updateParam('direction', direction === 'asc' ? 'desc' : 'asc', true)} aria-label="切换排序方向">{direction === 'asc' ? '升序 ↑' : '降序 ↓'}</button></div>
    {loading && <p role="status">正在加载证书…</p>}
    {!loading && error && <div role="alert">{error} <button type="button" onClick={() => setRevision(value => value + 1)}>重试列表</button></div>}
    {!loading && !error && data && (data.items.length === 0 ? <p className="empty-state">{search ? '没有匹配的证书' : '暂无证书'}</p> : <>
      <div className="table-scroll"><table><thead><tr><th>序列号</th><th>学员</th><th>课程</th><th>签发日期</th><th>状态</th></tr></thead><tbody>{data.items.map(item => <tr key={item.id}>
        <td><button type="button" className="text-button" onClick={() => setSelectedId(item.id)}>{item.serial_number}</button></td><td>{item.learner_name}</td><td>{item.course_title}</td><td>{item.issued_local_date}</td><td><span className={`status ${item.status.toLowerCase()}`}>{item.status === 'ACTIVE' ? '有效' : '已撤销'}</span></td>
      </tr>)}</tbody></table></div>
      <div className="pagination"><span>共 {data.total} 条 · 第 {page} 页</span><button type="button" disabled={page <= 1} onClick={() => updateParam('page', String(page - 1))}>上一页</button><button type="button" disabled={page * 20 >= data.total} onClick={() => updateParam('page', String(page + 1))}>下一页</button></div>
    </>)}
    {selectedId !== null && <CertificateDrawer id={selectedId} actorEmail={actorEmail} onClose={() => setSelectedId(null)} onChanged={() => setRevision(value => value + 1)} />}
  </section>
}
import { useEffect, useRef, useState } from 'react'
import type { RevokeResponse } from '../api/types'
import { createPendingWrite, loadPendingWrite, type PendingWrite } from '../lib/pendingWrite'
import { clearPendingWrite } from '../lib/pendingWrite'
import { submitWrite } from '../lib/writeRequest'
import { ApiError } from '../api/client'

type Props = { id: number; serial: string; actorEmail: string; onDone: () => void; onClose: () => void; onBeginWrite?: (key: string) => boolean; onEndWrite?: (key: string) => void }

export function RevokeDialog({ id, serial, actorEmail, onDone, onClose, onBeginWrite, onEndWrite }: Props) {
  const path = `/api/certificates/${id}/revoke`
  const [write, setWrite] = useState<PendingWrite | null>(() => {
    return loadPendingWrite(actorEmail, path)
  })
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [conflict, setConflict] = useState(false)
  const [result, setResult] = useState<RevokeResponse | null>(null)
  const confirmRef = useRef<HTMLButtonElement>(null)
  useEffect(() => { confirmRef.current?.focus() }, [])
  useEffect(() => {
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape' && !busy) onClose() }
    document.addEventListener('keydown', closeOnEscape)
    return () => document.removeEventListener('keydown', closeOnEscape)
  }, [busy, onClose])

  async function confirm() {
    const operation = write ?? createPendingWrite(actorEmail, path, {})
    if (onBeginWrite && !onBeginWrite(operation.key)) { setError('该操作正在处理中'); return }
    setWrite(operation); setBusy(true); setError(null); setConflict(false)
    try {
      const response = await submitWrite<RevokeResponse>(operation)
      setResult(response)
      onDone()
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : '请求结果不确定，请用原操作重试')
      setConflict(cause instanceof ApiError && cause.status === 409)
    } finally { setBusy(false); onEndWrite?.(operation.key) }
  }

  function discardConflict() {
    if (!conflict || busy) return
    const stale = write ?? loadPendingWrite(actorEmail, path)
    if (stale) clearPendingWrite(stale)
    setWrite(null); setError(null); setConflict(false); onClose()
  }

  return <div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true" aria-label="撤销证书确认">
    <h2>撤销证书</h2><p>请确认撤销以下证书：</p><strong>{serial}</strong>
    {result ? <p role="status">{result.changed ? '撤销成功' : '证书已撤销，无需重复操作'}</p> : <p>撤销后可再次颁发新证书，旧证书仍保留。</p>}
    {error && <p role="alert">{error}</p>}
    <div className="modal-actions"><button type="button" onClick={onClose} disabled={busy}>{result ? '关闭' : '取消'}</button>{!result && conflict && <button type="button" onClick={discardConflict} disabled={busy}>放弃冲突操作</button>}{!result && <button ref={confirmRef} type="button" onClick={confirm} disabled={busy}>{busy ? '处理中…' : error ? '用同一操作重试' : '确认撤销'}</button>}</div>
  </div></div>
}

