      {enrollmentsLoading ? <p role="status">正在加载学员…</p> : enrollmentsError ? <div role="alert">{enrollmentsError} <button onClick={() => setEnrollmentsRevision(value => value + 1)}>重试学员</button></div> : enrollments && <>
