        {rows.length === 0 ? <p className="empty-state">{enrollments.total === 0 ? '该课程暂无学员' : '当前页无学员'}</p> : <div className="table-scroll"><table><thead><tr><th>学员</th><th>完成状态</th><th>颁发资格</th></tr></thead><tbody>{rows.map(row => <tr key={row.learner_id}><td>{row.learner_name}</td><td>{row.status === 'COMPLETED' ? '已完成' : '未完成'}</td><td>{row.status === 'INCOMPLETE' ? '不可颁发' : row.active_certificate_id !== null ? <button type="button" className="text-button" onClick={() => setSelectedCertificateId(row.active_certificate_id)}>查看并撤销证书</button> : '可颁发'}</td></tr>)}</tbody></table></div>}
        {enrollments.total > 0 && <div className="pagination"><span>共 {enrollments.total} 名学员 · 第 {enrollments.page} / {totalPages} 页</span><button type="button" disabled={page <= 1} onClick={() => setPage(value => value - 1)}>上一页</button><button type="button" disabled={page >= totalPages} onClick={() => setPage(value => value + 1)}>下一页</button></div>}
