from .idempotency import execute_write, fingerprint


def courses_for_actor(conn: sqlite3.Connection, actor: ActorContext) -> dict:
    return {"items": list_courses(conn, actor.tenant_id)}


def enrollments_for_course(conn: sqlite3.Connection, actor: ActorContext, course_id: int, page: int, page_size: int) -> dict:
    course = get_course(conn, actor.tenant_id, course_id)
    if course is None:
        raise ApiError(404, "NOT_FOUND", "资源不存在")
    return {"course": course, **page_enrollments(conn, actor.tenant_id, course_id, page, page_size)}


def bulk_issue_course(path: Path, actor: ActorContext, course_id: int, key: str, body: dict) -> tuple[int, dict]:
    conn = connect(path)
    try:
        request_fingerprint = fingerprint("POST", "/api/courses/{course_id}/bulk-issue", course_id, body)

        def validate_new_request() -> None:
            if body:
                raise ApiError(422, "INVALID_REQUEST", "请求体不支持额外字段")
            if get_course(conn, actor.tenant_id, course_id) is None:
                raise ApiError(404, "NOT_FOUND", "资源不存在")

        def perform(record_id: int) -> tuple[int, dict]:
            outcomes = []
            for enrollment in list_enrollments(conn, actor.tenant_id, course_id):
                common = {
                    "learner_id": enrollment["learner_id"],
                    "learner_name": enrollment["learner_name"],
                    "certificate_id": None,
                    "serial_number": None,
                }
                if enrollment["status"] != "COMPLETED":
                    outcomes.append({**common, "result": "skipped", "reason": "课程未完成"})
                    continue
                if enrollment["active_certificate_id"] is not None:
                    outcomes.append({**common, "result": "skipped", "reason": "已有有效证书"})
                    continue

                issued_at = datetime.now(timezone.utc)
                issued_text = issued_at.isoformat(timespec="seconds").replace("+00:00", "Z")
                local_date, _ = to_local(issued_at, actor.timezone)
                serial = f"CERT-{uuid4().hex.upper()}"
                conn.execute("SAVEPOINT learner_issue")
                try:
                    certificate_id = create_certificate(
                        conn, actor.tenant_id, course_id, enrollment["learner_id"], serial, issued_text, local_date
                    )
                    record_event(conn, actor.tenant_id, certificate_id, actor.admin_id, "ISSUED", issued_text, record_id)
                except sqlite3.IntegrityError:
                    conn.execute("ROLLBACK TO SAVEPOINT learner_issue")
                    conn.execute("RELEASE SAVEPOINT learner_issue")
                    outcomes.append({**common, "result": "failed", "reason": "证书颁发失败"})
                else:
                    conn.execute("RELEASE SAVEPOINT learner_issue")
                    outcomes.append({**common, "result": "issued", "reason": None, "certificate_id": certificate_id, "serial_number": serial})

            summary = {name: sum(row["result"] == name for row in outcomes) for name in ("issued", "skipped", "failed")}
            return 200, {"operation_id": record_id, "status": "COMPLETED", "summary": summary, "outcomes": outcomes}

        return execute_write(conn, actor, key, request_fingerprint, "BULK_ISSUE", validate_new_request, perform)
    finally:
        conn.close()
import sqlite3


def list_courses(conn: sqlite3.Connection, tenant_id: int) -> list[dict]:
    return [dict(row) for row in conn.execute(
        "SELECT id, title FROM courses WHERE tenant_id = ? ORDER BY id", (tenant_id,)
    )]


def get_course(conn: sqlite3.Connection, tenant_id: int, course_id: int) -> dict | None:
    row = conn.execute(
        "SELECT id, title FROM courses WHERE tenant_id = ? AND id = ?", (tenant_id, course_id)
    ).fetchone()
    return dict(row) if row else None


def list_enrollments(conn: sqlite3.Connection, tenant_id: int, course_id: int) -> list[dict]:
    rows = conn.execute(
        "SELECT learners.id AS learner_id, learners.name AS learner_name, enrollments.status, "
        "certificates.id AS active_certificate_id "
        "FROM enrollments JOIN learners ON learners.id = enrollments.learner_id AND learners.tenant_id = enrollments.tenant_id "
        "LEFT JOIN certificates ON certificates.tenant_id = enrollments.tenant_id "
        "AND certificates.course_id = enrollments.course_id AND certificates.learner_id = enrollments.learner_id "
        "AND certificates.status = 'ACTIVE' "
        "WHERE enrollments.tenant_id = ? AND enrollments.course_id = ? ORDER BY learners.id",
        (tenant_id, course_id),
    )
    return [dict(row) for row in rows]


def page_enrollments(conn: sqlite3.Connection, tenant_id: int, course_id: int, page: int, page_size: int) -> dict:
    joins = (
        "FROM enrollments "
        "JOIN learners ON learners.id = enrollments.learner_id AND learners.tenant_id = enrollments.tenant_id "
        "LEFT JOIN certificates ON certificates.tenant_id = enrollments.tenant_id "
        "AND certificates.course_id = enrollments.course_id AND certificates.learner_id = enrollments.learner_id "
        "AND certificates.status = 'ACTIVE' "
        "WHERE enrollments.tenant_id = ? AND enrollments.course_id = ?"
    )
    conn.execute("BEGIN")
    try:
        counts = conn.execute(
            "SELECT COUNT(*) AS total, "
            "COALESCE(SUM(enrollments.status = 'COMPLETED'), 0) AS completed, "
            "COALESCE(SUM(certificates.id IS NOT NULL), 0) AS active_certificates " + joins,
            (tenant_id, course_id),
        ).fetchone()
        offset = (page - 1) * page_size
        rows = [] if offset >= counts["total"] else conn.execute(
            "SELECT learners.id AS learner_id, learners.name AS learner_name, enrollments.status, "
            "certificates.id AS active_certificate_id " + joins +
            " ORDER BY learners.id LIMIT ? OFFSET ?",
            (tenant_id, course_id, page_size, offset),
        ).fetchall()
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    total = counts["total"]
    completed = counts["completed"]
    return {
        "items": [dict(row) for row in rows], "page": page, "page_size": page_size, "total": total,
        "summary": {"completed": completed, "incomplete": total - completed, "active_certificates": counts["active_certificates"]},
    }

